files.content:
[hidden] {
  display: none !important;
}

:root {
  --bg-color: #121820;
  --card-bg: #1c2430;
  --accent-gold: #ffbe26;
  --text-main: #f3f6f9;
  --text-muted: #9aa8b9;
  --btn-disabled: #354253;
  --btn-active: #d99c15;
  --border-color: #2e3a4e;
  --focus-ring: #64b5f6;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  background-color: var(--bg-color);
  color: var(--text-main);
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
  font-size: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.miner-card {
  background-color: var(--card-bg);
  border: 3px solid var(--border-color);
  border-radius: 12px;
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.45);
  padding: 24px;
  width: 100%;
  max-width: 420px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.miner-header {
  text-align: center;
}

.miner-title {
  font-size: 24px;
  color: var(--accent-gold);
  letter-spacing: 0.5px;
  margin-bottom: 4px;
}

.miner-badge {
  font-size: 12px;
  font-weight: 700;
  color: var(--text-muted);
  letter-spacing: 1px;
}

.canvas-container {
  display: flex;
  justify-content: center;
  background-color: #0b0f15;
  border: 2px solid var(--border-color);
  border-radius: 8px;
  padding: 8px;
}

#pixelCanvas {
  image-rendering: pixelated;
  width: 100%;
  max-width: 320px;
  height: auto;
  aspect-ratio: 4 / 3;
}

.stats-panel {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.stat-box {
  background-color: #151b24;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  padding: 12px;
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.stat-label {
  font-size: 13px;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.stat-value {
  font-size: 22px;
  font-weight: 800;
  color: var(--accent-gold);
}

.action-panel {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.btn-buy {
  background-color: var(--accent-gold);
  color: #121820;
  border: 2px solid #e09f18;
  border-radius: 8px;
  padding: 14px 18px;
  font-size: 16px;
  font-weight: 700;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  transition: background-color 0.15s ease, transform 0.05s ease;
}

.btn-buy .btn-meta {
  font-size: 13px;
  font-weight: 600;
  opacity: 0.85;
}

.btn-buy:hover:not(:disabled) {
  background-color: #ffc94d;
}

.btn-buy:active:not(:disabled) {
  background-color: var(--btn-active);
  transform: scale(0.98);
}

.btn-buy:focus-visible {
  outline: 3px solid var(--focus-ring);
  outline-offset: 2px;
}

.btn-buy:disabled {
  background-color: var(--btn-disabled);
  color: #728197;
  border-color: #27313f;
  cursor: not-allowed;
  opacity: 0.7;
}

.item-counter {
  font-size: 14px;
  color: var(--text-muted);
  text-align: center;
}

@media (max-width: 360px) {
  .miner-card {
    padding: 16px;
  }
  .stat-value {
    font-size: 18px;
  }
  .btn-buy {
    font-size: 15px;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  const state = {
    gold: 0,
    baseRate: 1,
    drillCount: 0,
    drillCost: 10,
    drillRateBonus: 1
  };

  const goldDisplay = document.getElementById('goldDisplay');
  const rateDisplay = document.getElementById('rateDisplay');
  const buyDrillBtn = document.getElementById('buyDrillBtn');
  const drillCountDisplay = document.getElementById('drillCountDisplay');
  const drillCostDisplay = document.getElementById('drillCostDisplay');
  const canvas = document.getElementById('pixelCanvas');
  const ctx = canvas.getContext('2d');

  function getGoldPerSecond() {
    return state.baseRate + (state.drillCount * state.drillRateBonus);
  }

  function updateUI() {
    goldDisplay.textContent = state.gold;
    rateDisplay.textContent = `${getGoldPerSecond()} / sec`;
    drillCountDisplay.textContent = state.drillCount;
    drillCostDisplay.textContent = state.drillCost;

    const canAfford = state.gold >= state.drillCost;
    buyDrillBtn.disabled = !canAfford;
  }

  function tick() {
    state.gold += getGoldPerSecond();
    updateUI();
    renderCanvas();
  }

  function buyDrill() {
    if (state.gold >= state.drillCost) {
      state.gold -= state.drillCost;
      state.drillCount += 1;
      updateUI();
      renderCanvas();
    }
  }

  let animFrame = 0;
  function renderCanvas() {
    animFrame = (animFrame + 1) % 4;
    ctx.fillStyle = '#0f141c';
    ctx.fillRect(0, 0, 160, 120);

    // Ground / Cave rock
    ctx.fillStyle = '#263242';
    ctx.fillRect(0, 96, 160, 24);

    // Gold vein pixel deposits
    ctx.fillStyle = '#ffbe26';
    ctx.fillRect(24, 76, 16, 12);
    ctx.fillRect(28, 72, 8, 4);
    ctx.fillRect(116, 80, 20, 12);
    ctx.fillRect(122, 74, 10, 6);

    // Miner pickaxe animation
    ctx.fillStyle = '#f3f6f9';
    ctx.fillRect(52, 60, 8, 16); // Miner body
    ctx.fillStyle = '#e57373';
    ctx.fillRect(52, 52, 8, 8);  // Helmet

    ctx.fillStyle = '#9aa8b9';
    if (animFrame % 2 === 0) {
      ctx.fillRect(60, 64, 12, 4); // Pickaxe swing high
      ctx.fillRect(72, 60, 4, 12);
    } else {
      ctx.fillRect(60, 72, 12, 4); // Pickaxe strike low
      ctx.fillRect(72, 72, 4, 12);
    }

    // Drills rendered
    if (state.drillCount > 0) {
      ctx.fillStyle = '#81c784';
      const visibleDrills = Math.min(state.drillCount, 5);
      for (let i = 0; i < visibleDrills; i++) {
        const x = 90 + (i * 12);
        const y = 84 + (animFrame % 2 === 0 ? 0 : 2);
        ctx.fillRect(x, y, 6, 10);
        ctx.fillStyle = '#ffb74d';
        ctx.fillRect(x + 1, y + 10, 4, 4);
        ctx.fillStyle = '#81c784';
      }
    }
  }

  buyDrillBtn.addEventListener('click', buyDrill);

  // Initial render and timer loop
  updateUI();
  renderCanvas();
  setInterval(tick, 1000);
});
